package com.xyz.question_bank_management_system.modules.agent.controller;
import com.xyz.question_bank_management_system.common.ApiResponse;import com.xyz.question_bank_management_system.modules.agent.service.ResourceAssessmentReleaseService;import com.xyz.question_bank_management_system.util.SecurityContextUtil;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;import java.util.*;
@RestController @RequiredArgsConstructor public class ResourceAssessmentController {private final ResourceAssessmentReleaseService service;@PostMapping("/internal/v1/personalized-resources/{bundleCode}/hidden-assessments/{itemCode}/release")@PreAuthorize("hasAuthority('INTERNAL_SERVICE') or hasRole('ADMIN')")public ApiResponse<Map<String,Object>> release(@PathVariable String bundleCode,@PathVariable String itemCode,@RequestBody Map<String,Object> body){Long userId=Long.valueOf(String.valueOf(body.get("userId")));LocalDateTime expires=body.get("expiresAt")==null?null:LocalDateTime.parse(String.valueOf(body.get("expiresAt")));return ApiResponse.ok(Map.of("releaseCode",service.release(userId,bundleCode,itemCode,expires)));}@GetMapping("/api/v1/personalized-resources/{bundleCode}/assessments/active")@PreAuthorize("hasRole('STUDENT')")public ApiResponse<List<?>> active(@PathVariable String bundleCode){return ApiResponse.ok(service.active(SecurityContextUtil.getUserId(),bundleCode));}}
